input.command:
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# Query keys must stay within A-Z a-z 0-9 _ . - (Cirrus function URLs reject others with 400).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) a=${1#action=}; echo "${a%%&*}" ;; esac; }
EOF
sed -i 's|?/<操作名>`|?action=<操作名>`（キーに `/` を使うと関数 URL が 400 を返すため）`|' docs/framework.md
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action="?action=save"' || { echo "render"; fail=1; }
for p in event seat refund; do
  bash bin/render $p | grep -o 'action="[^"]*"' | grep -q '[^A-Za-z0-9_.=?-]' && { echo "render key chars $p"; fail=1; }
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^404' || { echo "old format"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo $?; cat app/forms/*.form; sed -n 1,3p docs/framework.md

